mapper.select:
SELECT om.*, ci.cluster_name, CONCAT(ec.service_name, ' - ', ec.service_role) AS service_label
FROM t_ddh_operations_management om
LEFT JOIN t_ddh_cluster_info ci ON om.cluster_id = ci.id
LEFT JOIN t_ddh_cluster_existing_component ec ON om.existing_component_id = ec.id
WHERE 1=1

    AND (
        om.service_name LIKE CONCAT('%', #{keyword}, '%')
        OR om.service_role LIKE CONCAT('%', #{keyword}, '%')
        OR om.operation_sub_type LIKE CONCAT('%', #{keyword}, '%')
        OR om.operator LIKE CONCAT('%', #{keyword}, '%')
        OR om.operation_result LIKE CONCAT('%', #{keyword}, '%')
    )


    AND om.cluster_id = #{clusterId}


    AND om.operation_type = #{operationType}


    AND om.operation_status = #{operationStatus}


    AND om.create_time >= #{startDate}


    AND om.create_time <= #{endDate}

ORDER BY om.create_time DESC

SELECT *
FROM t_ddh_operations_management
WHERE cluster_id = #{clusterId}
  AND operation_type = #{operationType}
ORDER BY create_time DESC

SELECT *
FROM t_ddh_operations_management
WHERE cluster_id = #{clusterId}
  AND operation_status = #{operationStatus}
ORDER BY create_time DESC

SELECT operation_type AS type, operation_sub_type AS sub_type, COUNT(*) AS count, AVG(duration_ms) AS avg_duration_ms, MAX(duration_ms) AS max_duration_ms, MIN(duration_ms) AS min_duration_ms, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY duration_ms) AS median_duration_ms FROM t_ddh_operations_management WHERE cluster_id = #{clusterId} AND operation_status IN ('SUCCESS', 'FAILED') AND duration_ms IS NOT NULL
AND operation_type = #{operationType}
GROUP BY operation_type, operation_sub_type ORDER BY avg_duration_ms DESC
